"""Transport-only SSE decoder. It never receives gold labels or NLI scores."""
import json


def decode_stream(lines):
    content, metadata = [], {}
    finish = None
    done = False
    for line in lines:
        text = line.decode('utf-8') if isinstance(line, bytes) else line
        text = text.strip()
        if not text.startswith('data:'):
            continue
        payload = text[5:].strip()
        if payload == '[DONE]':
            done = True
            break
        event = json.loads(payload)
        if 'error' in event:
            raise RuntimeError('provider error: ' + str(event['error'])[:300])
        for key in ['id', 'model', 'created', 'usage']:
            if key in event:
                metadata[key] = event[key]
        choices = event.get('choices', [])
        if not choices:
            continue
        choice = choices[0]
        chunk = choice.get('delta', {}).get('content')
        if chunk:
            if not isinstance(chunk, str):
                raise RuntimeError('unexpected content type')
            content.append(chunk)
        if choice.get('finish_reason') is not None:
            finish = choice['finish_reason']
    if not done or finish is None:
        raise RuntimeError('incomplete SSE response; refusing to cache')
    if finish != 'stop':
        raise RuntimeError(f'non-stop completion ({finish}); refusing to cache')
    return {**metadata, 'choices': [{'index': 0, 'message': {'role': 'assistant', 'content': ''.join(content)}, 'finish_reason': finish}]}
